import { existsSync } from "node:fs";
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath, pathToFileURL } from "node:url";
import bs58 from "bs58";

export const VAULT_CRATE = "probarion-vault";
const SOURCE = new URL("../../../contracts/code-hashes.json", import.meta.url);
const TARGET = new URL("../src/code-hashes.ts", import.meta.url);
/** biome.json formatter.lineWidth: the generated file is written in the form `biome format` leaves unchanged. */
const LINE_WIDTH = 100;

/**
 * The base58 code hashes of every recorded probarion-vault build, once each, in record order.
 * Only `crate === "probarion-vault"` entries count: contracts/code-hashes.json also records the
 * probarion-factory builds, and a factory's hash must never be trusted as a vault. Every other field
 * of an entry (version, tree, workspace, lock, commit, built_with, recorded_at, anything added later) is ignored.
 */
export function vaultHashesFrom(json: unknown): string[] {
  const entries =
    typeof json === "object" &&
    json !== null &&
    Array.isArray((json as { entries?: unknown }).entries)
      ? (json as { entries: unknown[] }).entries
      : [];
  const hashes: string[] = [];
  for (const entry of entries) {
    if (typeof entry !== "object" || entry === null) continue;
    const rec = entry as Record<string, unknown>;
    if (
      rec.crate === VAULT_CRATE &&
      typeof rec.code_hash === "string" &&
      !hashes.includes(rec.code_hash)
    ) {
      hashes.push(rec.code_hash);
    }
  }
  return hashes;
}

/** The text of src/code-hashes.ts. Deterministic, LF only, and already in the form `biome format` produces. */
export function renderCodeHashes(hashes: readonly string[]): string {
  const declaration = "export const KNOWN_VAULT_CODE_HASHES: readonly string[] = ";
  const oneLine = `${declaration}[${hashes.map((h) => JSON.stringify(h)).join(", ")}];`;
  const statement =
    oneLine.length <= LINE_WIDTH
      ? oneLine
      : `${declaration}[\n${hashes.map((h) => `  ${JSON.stringify(h)},`).join("\n")}\n];`;
  return [
    "// GENERATED by `pnpm --filter @probarion/core sync-code-hashes` from contracts/code-hashes.json (plan 02). Do not edit.",
    "/** Vault wasm code hashes (base58 of sha256, as NEAR view_account.code_hash reports them) from reproducible builds. Check f trusts these plus the versions of the canonical factory, and nothing the snapshot lists. */",
    statement,
    "",
  ].join("\n");
}

/** A hash that is not 32 bytes of base58 would silently never match; stop the sync instead of generating it. */
function assertSha256(hash: string): void {
  let length = -1;
  try {
    length = bs58.decode(hash).length;
  } catch {
    // length stays -1
  }
  if (length !== 32) {
    throw new Error(
      `code_hash ${JSON.stringify(hash)} in contracts/code-hashes.json is not a base58 sha256 hash`,
    );
  }
}

async function main(): Promise<void> {
  if (!existsSync(SOURCE)) {
    process.stderr.write(`${fileURLToPath(SOURCE)} does not exist yet (plan 02 creates it)\n`);
    process.exit(2);
  }
  const hashes = vaultHashesFrom(JSON.parse(await readFile(SOURCE, "utf8")));
  for (const hash of hashes) assertSha256(hash);
  await writeFile(TARGET, renderCodeHashes(hashes), "utf8");
  process.stdout.write(`wrote ${hashes.length} vault code hash(es) to ${fileURLToPath(TARGET)}\n`);
}

const invoked = process.argv[1];
if (invoked !== undefined && import.meta.url === pathToFileURL(invoked).href) {
  await main();
}
